def _T(theta, s, tm):
    c, sn = math.cos(theta), math.sin(theta)
    tx, ty = tm * math.cos(PHI), tm * math.sin(PHI)

    def pt(p):
        return (s * (c * p[0] - sn * p[1]) + tx, s * (sn * p[0] + c * p[1]) + ty)

    def vec(v):                       # 平移量/方向：只转、只缩，不平移
        return (s * (c * v[0] - sn * v[1]), s * (sn * v[0] + c * v[1]))

    def poly(P):
        return [pt(p) for p in P]
    return pt, vec, poly

